/**
 * The Knowledge Centre's articles, migrated from the WordPress site this one
 * replaces.
 *
 * Seventy-three pieces, roughly a hundred thousand words, and the reason the
 * migration mattered: these are what rank for the questions people actually
 * search — what a programme costs, whether a property qualifies, what happens
 * after three years. The rebuild had none of it.
 *
 * Seventy-one came from `scripts/migrate-legacy.mjs`, which reads the legacy
 * REST API and so only ever sees published posts. The last two were drafts,
 * finished but never published there, and came from the export file via
 * `scripts/import-wxr.mjs`. Two things to know when editing:
 *
 *  - A `body` entry beginning `## ` is a heading; everything else is a
 *    paragraph. That is how the legacy structure survived the move without
 *    carrying HTML across.
 *  - `tables` hold the comparison grids, which is where most of the value in
 *    these pieces sits.
 *
 * ─────────────────────────────────────────────────────────────────────────
 * UNRECONCILED. This prose states thresholds and processing times as fact,
 * and the legacy articles do not agree with each other — several still quote
 * Türkiye's pre-2022 threshold of USD 250,000 against the USD 400,000 the
 * rest of the site states. Run `node scripts/migrate-legacy.mjs` to see the
 * conflict report. Every figure has to be reconciled against
 * `app/lib/figures.ts` before these are published.
 * ─────────────────────────────────────────────────────────────────────────
 */

