    date: "2026-08-06",
    modified: "2026-08-06",
    topics: ["turkiye"],
    excerpt: "In an unprecedented crackdown on real estate fraud, Turkish authorities recently announced legal proceedings to revoke the citizenship of 687 foreign nationals. Following coordinated police raids across 16 provinces centered in Istanbul, Justice Minister Ak\u0131n G\u00fcrlek revealed an organized criminal network that manipulated real estate transactions to exploit the Turkish Citizenship by Investment (CBI) program. [\u2026]",
