      "## Step 2: Select the Right Property",
      "Turkey has a diverse real estate market, ranging from luxury residences in Istanbul to coastal properties in Antalya and Alanya and emerging investment locations throughout the country.",
      "Foreign investors should evaluate more than the advertised price.",
      "Important considerations include:",
      "Location",
      "Developer reputation",
