      "According to official figures from the Central Bank of the Republic of T\u00fcrkiye (TCMB), foreign real estate investment in T\u00fcrkiye surged by 28.3% year-on-year across March, April, and May, totaling $590 million. As global uncertainty prompts buyers to reconsider alternative markets like Dubai or Mediterranean Europe, T\u00fcrkiye\u2019s housing market is standing out for its resilience, strong diplomatic stance, and competitive pricing.",
      "Here is a closer look at what is driving this capital inflow and why now is an opportunistic moment for global investors to secure property in T\u00fcrkiye.",
