      "As of July 2025, the program has granted citizenship to over 35,000 foreign nationals, generating more than $250 million in monthly revenue for the Turkish economy. [23] From January to November 2025 alone, Turkey attracted $12.4 billion in foreign direct investment, a remarkable 28% increase over the same period in 2024. [22]",
